/**
 * HTML → plain text, for building the searchable body of a post.
 *
 * Deliberately dependency-free and regex-based: it is shared by the build
 * script (scripts/generate-posts.js, which `require`s this .ts file and relies
 * on Node >= 22.18 type stripping) and the server-side data layer, and the
 * input is always generated by remark-html from our own Markdown, so no full
 * HTML parser is warranted.
 */

const NAMED_ENTITIES: Record<string, string> = {
  amp: "&",
  lt: "<",
  gt: ">",
  quot: '"',
  apos: "'",
  nbsp: " ",
};

export function plainTextFromHtml(html: string): string {
  if (!html) return "";

  return html
    // remark-html emits fenced code as <pre><code>…</code></pre>; code should
    // not pollute search results, so drop those blocks whole.
    .replace(/<pre[\s\S]*?<\/pre>/gi, " ")
    .replace(/<[^>]*>/g, " ")
    .replace(/&#(\d+);/g, (_, code) => String.fromCodePoint(Number(code)))
    .replace(/&#x([0-9a-f]+);/gi, (_, code) => String.fromCodePoint(parseInt(code, 16)))
    .replace(/&([a-z]+);/gi, (entity, name: string) => NAMED_ENTITIES[name.toLowerCase()] ?? entity)
    .replace(/\s+/g, " ")
    .trim();
}
